import"./chunk-VC46IEJQ.js";var t=([o,a])=>({en:o,zh:a}),e=(o,a,i,n,r,h,d,l,s)=>({name:t(o),desc:t(a),tour:t(i),...s?{spoiler:t(s)}:{},source:{confidence:n,refs:r,book:t(h),unknown:t(d),interpretation:t(l)}}),c={id:"casterly-rock",intro:{en:"Casterly Rock, seat of House Lannister, is a vast rock above the Sunset Sea, honeycombed with halls, cellars and old mine-workings. Its great cavern entrance is called the Lion's Mouth, and the port of Lannisport lies at its foot.",zh:"\u51EF\u5CA9\u57CE\u662F\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4E00\u5EA7\u4FEF\u4E34\u65E5\u843D\u4E4B\u6D77\u7684\u5DE8\u5CA9\uFF0C\u5CA9\u5185\u5385\u5802\u3001\u5730\u7A96\u4E0E\u65E7\u77FF\u9053\u7EB5\u6A2A\u4EA4\u9519\u3002\u5DE8\u5927\u7684\u6D1E\u7A9F\u5165\u53E3\u540D\u4E3A\u201C\u72EE\u53E3\u201D\uFF0C\u5170\u5C3C\u65AF\u6E2F\u5C31\u5728\u5CA9\u811A\u4E0B\u3002"},notes:{en:"From the novels: a great rock by the sea, Lannister wealth from its gold mines, Lannisport below, and (in Tyrion's memories) the Lion's Mouth and the castle's drains and cisterns. From The World of Ice & Fire, via wiki summaries: the Lion's Mouth's scale, a stair wide enough for many riders, sea gates for ships, and a summit watchtower used as a rookery. Invented: the rock's shape, the stair, summit walls, mine positions and every exterior detail. Most of the castle lies inside the rock and is not shown.",zh:"\u5C0F\u8BF4\u786E\u7ACB\uFF1A\u4E34\u6D77\u5DE8\u5CA9\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u8D22\u5BCC\u6765\u81EA\u5CA9\u4E2D\u91D1\u77FF\uFF0C\u5CA9\u4E0B\u662F\u5170\u5C3C\u65AF\u6E2F\uFF1B\u63D0\u5229\u6602\u7684\u56DE\u5FC6\u4E2D\u8FD8\u63D0\u5230\u72EE\u53E3\uFF0C\u4EE5\u53CA\u57CE\u4E2D\u7684\u6392\u6C34\u9053\u4E0E\u84C4\u6C34\u6C60\u3002\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u8865\u5145\u4E86\u72EE\u53E3\u7684\u89C4\u6A21\u3001\u53EF\u5BB9\u591A\u9A91\u5E76\u884C\u7684\u9636\u68AF\u3001\u4F9B\u8239\u53EA\u51FA\u5165\u7684\u6D77\u95E8\uFF0C\u4EE5\u53CA\u5CA9\u9876\u517C\u4F5C\u9E26\u5DE2\u7684\u77AD\u671B\u5854\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5CA9\u4F53\u5F62\u72B6\u3001\u9636\u68AF\u3001\u5CA9\u9876\u57CE\u5899\u3001\u77FF\u6D1E\u4F4D\u7F6E\u53CA\u4E00\u5207\u5916\u89C2\u7EC6\u8282\u3002\u57CE\u5821\u5927\u90E8\u5206\u6DF1\u85CF\u5CA9\u4E2D\uFF0C\u672A\u4E88\u8868\u73B0\u3002"},tour:["the-rock","sea-cliffs","lions-mouth","great-stair","summit-crown","rookery-tower","gold-mines","sea-gate","private-docks","ocean-road"],sources:[{ref:"asos",checked:"memory",note:{en:"Tyrion recalls the Rock (the Lion's Mouth, the drains and cisterns he was given charge of); the castle is never visited on-page in the five novels. Recalled, not re-read.",zh:"\u63D0\u5229\u6602\u56DE\u5FC6\u8D77\u51EF\u5CA9\u57CE\uFF08\u72EE\u53E3\uFF0C\u4EE5\u53CA\u66FE\u4EA4\u7531\u4ED6\u638C\u7BA1\u7684\u6392\u6C34\u9053\u4E0E\u84C4\u6C34\u6C60\uFF09\uFF1B\u4E94\u90E8\u5C0F\u8BF4\u4E2D\u4ECE\u672A\u6709\u573A\u666F\u76F4\u63A5\u53D1\u751F\u5728\u57CE\u5185\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"The Lion's Mouth (about 200 ft high), a stair for twenty riders abreast, sea gates for galleys and cogs, and the summit watchtower are attributed by wiki summaries to TWOIAF's Westerlands chapter. The book itself was not consulted.",zh:"\u72EE\u53E3\uFF08\u9AD8\u7EA6\u4E24\u767E\u5C3A\uFF09\u3001\u53EF\u5BB9\u4E8C\u5341\u9A91\u5E76\u884C\u7684\u9636\u68AF\u3001\u53EF\u4F9B\u6868\u5E06\u8239\u4E0E\u67EF\u514B\u8239\u51FA\u5165\u7684\u6D77\u95E8\uFF0C\u4EE5\u53CA\u5CA9\u9876\u77AD\u671B\u5854\uFF0C\u636E\u7EF4\u57FA\u6458\u8981\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u7684\u897F\u5883\u4E00\u7AE0\u3002\u539F\u4E66\u672A\u67E5\u9605\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:'Wiki summaries of the Rock and its caverns; pages not fetched. A claim that the gold mines have "run dry" could not be traced to the novels (it is familiar from the TV series) and has been removed.',zh:"\u51EF\u5CA9\u57CE\u53CA\u5CA9\u4E0B\u6D1E\u7A9F\u7684\u7EF4\u57FA\u6458\u8981\uFF1B\u9875\u9762\u672A\u6293\u53D6\u3002\u201C\u91D1\u77FF\u5DF2\u7ECF\u67AF\u7AED\u201D\u4E00\u8BF4\u65E0\u6CD5\u5728\u5C0F\u8BF4\u4E2D\u627E\u5230\u51FA\u5904\uFF08\u5B83\u6E90\u81EA\u7535\u89C6\u5267\uFF09\uFF0C\u5DF2\u4E88\u5220\u9664\u3002"}}],landmarks:{"the-rock":e(["Casterly Rock","\u51EF\u5CA9\u57CE"],["A colossal rock rising above the Sunset Sea, said to resemble a lion at rest, with the castle hollowed out inside it.","\u4FEF\u4E34\u65E5\u843D\u4E4B\u6D77\u7684\u5E9E\u7136\u5DE8\u5CA9\uFF0C\u636E\u8BF4\u5F62\u4F3C\u4E00\u5934\u4F0F\u5367\u7684\u96C4\u72EE\uFF0C\u57CE\u5821\u5C31\u51FF\u5728\u5CA9\u4E2D\u3002"],["Nearly the whole castle lies inside the stone, above the harbour and the sea.","\u51E0\u4E4E\u6574\u5EA7\u57CE\u5821\u90FD\u85CF\u5728\u5CA9\u77F3\u91CC\uFF0C\u4FEF\u77B0\u6E2F\u53E3\u4E0E\u5927\u6D77\u3002"],"medium",["agot","asos","twoiaf"],["A great rock by the sea, seat of the Lannisters, hollowed into halls and passages; the lion-at-rest likeness is a companion-book detail.","\u4E34\u6D77\u5DE8\u5CA9\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5185\u90E8\u51FF\u6210\u5385\u5802\u4E0E\u901A\u9053\uFF1B\u201C\u5F62\u5982\u5367\u72EE\u201D\u51FA\u81EA\u8BBE\u5B9A\u96C6\u3002"],["The rock's true size and outline, and the interior layout.","\u5CA9\u4F53\u7684\u771F\u5B9E\u5927\u5C0F\u4E0E\u8F6E\u5ED3\uFF0C\u4EE5\u53CA\u5185\u90E8\u5E03\u5C40\u3002"],["Three humped masses form a crouching silhouette with sandstone strata; heights are scaled for viewing.","\u4E09\u5EA7\u9686\u8D77\u7684\u5CA9\u4F53\u7EC4\u6210\u4F0F\u5367\u7684\u526A\u5F71\uFF0C\u5E26\u7802\u5CA9\u5C42\u7406\uFF1B\u9AD8\u5EA6\u4E3A\u4FBF\u4E8E\u89C2\u8D4F\u800C\u7F29\u653E\u3002"]),"sea-cliffs":e(["Sea Cliffs","\u4E34\u6D77\u5CED\u58C1"],["The western face drops sheer into the surf; stacked strata glow gold and red in the sun.","\u897F\u4FA7\u5CA9\u58C1\u9661\u76F4\u63D2\u5165\u6D6A\u6D9B\uFF0C\u5C42\u5C42\u5CA9\u7406\u5728\u9633\u5149\u4E0B\u6CDB\u7740\u91D1\u7EA2\u3002"],["The Rock's sea face rises from the surf, gold and rust in the evening light.","\u5DE8\u5CA9\u4E34\u6D77\u7684\u4E00\u9762\u62D4\u6D6A\u800C\u8D77\uFF0C\u66AE\u8272\u4E2D\u91D1\u7EA2\u4EA4\u6620\u3002"],"low",["twoiaf"],["The Rock stands over the sea; no detailed cliff description is known to us.","\u5DE8\u5CA9\u4FEF\u4E34\u5927\u6D77\uFF1B\u5C31\u6211\u4EEC\u6240\u77E5\uFF0C\u5E76\u65E0\u5BF9\u5CED\u58C1\u7684\u8BE6\u7EC6\u63CF\u5199\u3002"],["Height, colour and shoreline details.","\u9AD8\u5EA6\u3001\u989C\u8272\u4E0E\u6D77\u5CB8\u7EC6\u8282\u3002"],["Terraced cliffs and a rocky shore, chosen for drama.","\u4E3A\u6C42\u620F\u5267\u6548\u679C\u800C\u8BBE\u8BA1\u7684\u5C42\u53E0\u5CED\u58C1\u4E0E\u7901\u5CB8\u3002"]),"lions-mouth":e(["Lion's Mouth","\u72EE\u53E3"],["A towering cavern in the south face, the Rock's main entrance, framed by jambs and a heavy lintel with jagged stone teeth.","\u5357\u4FA7\u5CA9\u58C1\u4E0A\u7684\u9AD8\u8038\u6D1E\u7A9F\uFF0C\u662F\u4E3B\u5165\u53E3\uFF0C\u4E24\u4FA7\u5CA9\u67F1\u6491\u7740\u539A\u91CD\u95E8\u6963\uFF0C\u8FB9\u7F18\u5D4C\u7740\u53C2\u5DEE\u77F3\u9F7F\u3002"],["The great cave mouth through which the castle is entered.","\u8FDB\u5165\u57CE\u5821\u7684\u5DE8\u5927\u6D1E\u53E3\u3002"],"medium",["asos","twoiaf","awoiaf"],["The Rock's main entrance is a huge cavern called the Lion's Mouth; Tyrion mentions it in the novels, and the companion book gives it about 200 ft in height.","\u51EF\u5CA9\u57CE\u7684\u4E3B\u5165\u53E3\u662F\u4E00\u5904\u540D\u4E3A\u201C\u72EE\u53E3\u201D\u7684\u5DE8\u5927\u6D1E\u7A9F\uFF1B\u5C0F\u8BF4\u4E2D\u63D0\u5229\u6602\u63D0\u5230\u8FC7\u5B83\uFF0C\u8BBE\u5B9A\u96C6\u79F0\u5176\u9AD8\u7EA6\u4E24\u767E\u5C3A\u3002"],["What lies just inside, and how the opening looks.","\u6D1E\u5185\u60C5\u5F62\uFF0C\u4EE5\u53CA\u6D1E\u53E3\u7684\u5177\u4F53\u6837\u8C8C\u3002"],["A framed dark opening with stone teeth, scaled lower than the quoted height.","\u5E26\u77F3\u9F7F\u7684\u5E7D\u6697\u6D1E\u53E3\uFF0C\u9AD8\u5EA6\u4F4E\u4E8E\u8BBE\u5B9A\u6570\u636E\u3002"]),"great-stair":e(["The Great Stair","\u5927\u9636\u68AF"],["A broad stair climbing from the plain to the cavern mouth, wide enough for many riders abreast.","\u81EA\u5E73\u539F\u76F4\u4E0A\u6D1E\u53E3\u7684\u5BBD\u9614\u957F\u9636\uFF0C\u53EF\u5BB9\u591A\u9A91\u5E76\u884C\u3002"],["A stair wide enough for twenty riders climbs to the Lion's Mouth.","\u4E00\u9053\u53EF\u5BB9\u4E8C\u5341\u9A91\u5E76\u884C\u7684\u9636\u68AF\u76F4\u901A\u72EE\u53E3\u3002"],"low",["twoiaf","awoiaf"],["A wide approach to the cavern, wide enough for twenty riders abreast, is attributed to the companion book by wiki summaries.","\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u8BBE\u5B9A\u96C6\u79F0\u901A\u5F80\u6D1E\u53E3\u7684\u9053\u8DEF\u5BBD\u53EF\u5BB9\u4E8C\u5341\u9A91\u5E76\u884C\u3002"],["Number of steps, the true width, and whether it is a stair or a road.","\u53F0\u9636\u6570\u91CF\u3001\u5B9E\u9645\u5BBD\u5EA6\uFF0C\u4EE5\u53CA\u7A76\u7ADF\u662F\u9636\u68AF\u8FD8\u662F\u5761\u9053\u3002"],["A broad stair cut into the slope with low balustrades and torches.","\u5207\u5165\u5C71\u5761\u7684\u5BBD\u9636\uFF0C\u914D\u77EE\u680F\u4E0E\u706B\u70AC\u3002"]),"summit-crown":e(["Summit Walls","\u5CA9\u9876\u57CE\u579B"],["Battlemented walls and red-roofed towers crown the highest hump of the Rock, banners snapping above.","\u6700\u9AD8\u7684\u5CA9\u5CF0\u4E0A\u7B51\u6709\u579B\u5899\u4E0E\u7EA2\u9876\u5854\u697C\uFF0C\u65D7\u5E1C\u730E\u730E\u4F5C\u54CD\u3002"],["Walls and towers on the summit fly crimson and gold banners.","\u5CA9\u9876\u7684\u57CE\u5899\u4E0E\u5854\u697C\u4E0A\uFF0C\u7329\u7EA2\u4E0E\u91D1\u8272\u7684\u65CC\u65D7\u98D8\u626C\u3002"],"low",["twoiaf"],["Little of the castle is built above ground; a watchtower on top is the exception (per wiki summaries of the companion book).","\u57CE\u5821\u5730\u9762\u5EFA\u7B51\u6781\u5C11\uFF0C\u5CA9\u9876\u7684\u77AD\u671B\u5854\u662F\u4F8B\u5916\uFF08\u636E\u7EF4\u57FA\u5BF9\u8BBE\u5B9A\u96C6\u7684\u6458\u8981\uFF09\u3002"],["Whether the summit is walled at all.","\u5CA9\u9876\u662F\u5426\u771F\u6709\u57CE\u5899\u3002"],["A ring wall with towers and a small keep, invented to give the skyline definition.","\u4E3A\u4F7F\u5929\u9645\u7EBF\u66F4\u9C9C\u660E\u800C\u865A\u6784\u7684\u73AF\u5899\u3001\u5854\u697C\u4E0E\u5C0F\u578B\u4E3B\u697C\u3002"]),"rookery-tower":e(["Rookery Tower","\u9E26\u5DE2\u5854"],["A slender watchtower on the summit where the maesters keep their ravens.","\u5CA9\u9876\u7684\u7EC6\u9AD8\u77AD\u671B\u5854\uFF0C\u5B66\u58EB\u5728\u6B64\u9972\u517B\u6E21\u9E26\u3002"],["Ravens for messages live in the Rock's lone tall tower.","\u4F20\u4FE1\u7684\u6E21\u9E26\u5C31\u4F4F\u5728\u5CA9\u9876\u552F\u4E00\u7684\u9AD8\u5854\u91CC\u3002"],"low",["twoiaf","awoiaf"],["A summit watchtower serves as the rookery, according to wiki summaries of the companion book.","\u636E\u7EF4\u57FA\u5BF9\u8BBE\u5B9A\u96C6\u7684\u6458\u8981\uFF0C\u5CA9\u9876\u7684\u77AD\u671B\u5854\u517C\u4F5C\u9E26\u5DE2\u3002"],["Height and design of the tower.","\u5854\u7684\u9AD8\u5EA6\u4E0E\u9020\u578B\u3002"],["A round tower with a gilded cap and circling ravens.","\u5706\u5854\uFF0C\u9540\u91D1\u5854\u9876\uFF0C\u7FA4\u9E26\u76D8\u65CB\u3002"]),"gold-mines":e(["Gold Mines","\u91D1\u77FF"],["Adits, spoil heaps and tracks pock the northern flank; Lannister gold is proverbial.","\u5317\u5761\u77FF\u6D1E\u3001\u6E23\u5806\u4E0E\u8F68\u9053\u661F\u7F57\u68CB\u5E03\uFF1B\u5170\u5C3C\u65AF\u7279\u7684\u9EC4\u91D1\u65E9\u5DF2\u6210\u4E3A\u8C1A\u8BED\u3002"],["Gold from the Rock made the Lannisters the richest house in Westeros.","\u5CA9\u4E2D\u7684\u9EC4\u91D1\uFF0C\u8BA9\u5170\u5C3C\u65AF\u7279\u6210\u4E3A\u7EF4\u65AF\u7279\u6D1B\u6700\u5BCC\u6709\u7684\u5BB6\u65CF\u3002"],"medium",["agot","twoiaf"],["Lannister wealth comes from the gold mines in and around the Rock, worked for thousands of years. The novels do not state that the mines have run dry; that idea comes from the TV series.","\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u8D22\u5BCC\u6765\u81EA\u5DE8\u5CA9\u5185\u5916\u5F00\u91C7\u4E86\u6570\u5343\u5E74\u7684\u91D1\u77FF\u3002\u5C0F\u8BF4\u4ECE\u672A\u8BF4\u8FC7\u91D1\u77FF\u5DF2\u7ECF\u67AF\u7AED\uFF0C\u90A3\u662F\u7535\u89C6\u5267\u7684\u60C5\u8282\u3002"],["Where the mines lie and how they connect to the castle.","\u77FF\u6D1E\u7684\u4F4D\u7F6E\u53CA\u4E0E\u57CE\u5821\u7684\u8FDE\u901A\u65B9\u5F0F\u3002"],["Five adits with spoil heaps and tracks on the north flank.","\u5317\u5761\u4E94\u5904\u77FF\u6D1E\uFF0C\u914D\u6E23\u5806\u4E0E\u8F68\u9053\u3002"]),"sea-gate":e(["Sea Gate","\u6D77\u95E8"],["A cave-mouth at the foot of the western cliff through which ships can enter beneath the Rock.","\u897F\u4FA7\u5D16\u811A\u7684\u6D1E\u53E3\uFF0C\u8239\u53EA\u53EF\u7531\u6B64\u9A76\u5165\u5DE8\u5CA9\u4E4B\u4E0B\u3002"],["Ships can sail right into the caverns beneath the Rock.","\u8239\u53EA\u53EF\u4EE5\u76F4\u63A5\u9A76\u8FDB\u5DE8\u5CA9\u4E0B\u7684\u6D1E\u7A9F\u3002"],"low",["twoiaf","awoiaf"],["Sea gates in the west face let galleys and cogs sail into caverns under the stone, per wiki summaries of the companion book.","\u636E\u7EF4\u57FA\u5BF9\u8BBE\u5B9A\u96C6\u7684\u6458\u8981\uFF0C\u897F\u4FA7\u5CA9\u58C1\u6709\u6D77\u95E8\uFF0C\u6868\u5E06\u8239\u4E0E\u67EF\u514B\u8239\u53EF\u9A76\u5165\u5CA9\u4E0B\u6D1E\u7A9F\u3002"],["Number and size of the gates.","\u6D77\u95E8\u7684\u6570\u91CF\u4E0E\u5C3A\u5BF8\u3002"],["One arched gate with a gatehouse in the west cliff.","\u897F\u4FA7\u5D16\u58C1\u4E0A\u4E00\u5EA7\u62F1\u5F62\u6D77\u95E8\u4E0E\u95E8\u697C\u3002"]),"private-docks":e(["Private Docks","\u79C1\u5BB6\u7801\u5934"],["Wooden piers by the sea gate where Lannister galleys are moored.","\u6D77\u95E8\u65C1\u7684\u6728\u6808\u6865\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u7684\u6868\u5E06\u8239\u6CCA\u5728\u8FD9\u91CC\u3002"],["The family's ships moor under the cliff.","\u5BB6\u65CF\u7684\u8239\u53EA\u6CCA\u5728\u5D16\u4E0B\u3002"],"low",["awoiaf"],["Only that ships can enter caverns under the Rock; no docks are described.","\u53EA\u77E5\u8239\u53EA\u53EF\u9A76\u5165\u5CA9\u4E0B\u6D1E\u7A9F\uFF1B\u7801\u5934\u672C\u8EAB\u672A\u89C1\u63CF\u5199\u3002"],["Dock layout and fleet size.","\u7801\u5934\u5E03\u5C40\u4E0E\u8239\u961F\u89C4\u6A21\u3002"],["Two piers and a few moored ships, placed outside the gate.","\u6D77\u95E8\u5916\u4E24\u5EA7\u6808\u6865\u4E0E\u6570\u8258\u6CCA\u8239\u3002"]),"ocean-road":e(["Road to Lannisport","\u5170\u5C3C\u65AF\u6E2F\u5927\u9053"],["A paved road runs from the foot of the stair across scrub and farmland to the port.","\u77F3\u677F\u8DEF\u81EA\u9636\u68AF\u811A\u4E0B\u51FA\u53D1\uFF0C\u7A7F\u8FC7\u704C\u4E1B\u4E0E\u519C\u7530\uFF0C\u901A\u5F80\u6E2F\u53E3\u3002"],["From the stair, the road leads down to the city below.","\u4ECE\u9636\u68AF\u811A\u4E0B\u51FA\u53D1\uFF0C\u5927\u8DEF\u901A\u5F80\u5CA9\u4E0B\u7684\u57CE\u5E02\u3002"],"medium",["agot","maps"],["Lannisport lies at the foot of the Rock.","\u5170\u5C3C\u65AF\u6E2F\u4F4D\u4E8E\u5DE8\u5CA9\u811A\u4E0B\u3002"],["The road's exact route and length.","\u9053\u8DEF\u7684\u786E\u5207\u8D70\u5411\u4E0E\u957F\u5EA6\u3002"],["A curving road with a small hamlet; see the Lannisport scene for the city itself.","\u873F\u8712\u5927\u9053\u4E0E\u4E00\u5904\u5C0F\u6751\uFF1B\u57CE\u5E02\u672C\u8EAB\u89C1\u5170\u5C3C\u65AF\u6E2F\u573A\u666F\u3002"])}};export{c as default};
